/**
 * Unicode character-class helpers that mirror the predicates CPython relies on.
 *
 * Everything here is derived from the JavaScript engine's own Unicode tables via
 * RegExp property escapes, so no data files or third-party packages are needed.
 */

/**
 * CPython's `Py_UNICODE_ISPRINTABLE` treats a character as non-printable when its
 * general category is one of the "Other" (Cc, Cf, Cs, Co, Cn) or "Separator"
 * (Zs, Zl, Zp) categories.  ASCII space is the single explicit exception.
 */
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

const DECIMAL_DIGIT = /^\p{Nd}$/u;

/** True when `ch` (a single code point) would satisfy Python's `str.isprintable()`. */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

