/**
 * Code points that Python's `str.splitlines()` treats as line boundaries.  Note
 * this is a wider set than `\n` alone: it includes the C0 separators and the
 * Unicode line/paragraph separators.
 */
const LINE_BOUNDARIES = new Set([
  0x0a, // \n  line feed
  0x0b, // \v  line tabulation
  0x0c, // \f  form feed
  0x0d, // \r  carriage return
  0x1c, // file separator
  0x1d, // group separator
  0x1e, // record separator
  0x85, // next line
  0x2028, // line separator
  0x2029, // paragraph separator
]);

/**
 * Python's `str.splitlines()`: split on any line boundary, treat CRLF as one
 * boundary, and never produce a trailing empty element for a terminating break.
 */
export function splitlines(s) {
  const out = [];
  let start = 0;
  let i = 0;
  while (i < s.length) {
    const code = s.charCodeAt(i);
    if (!LINE_BOUNDARIES.has(code)) {
      i += 1;
      continue;
    }
    out.push(s.slice(start, i));
    if (code === 0x0d && i + 1 < s.length && s.charCodeAt(i + 1) === 0x0a) i += 1;
    i += 1;
    start = i;
  }
  if (start < s.length) out.push(s.slice(start));
  return out;
}

/** Python's `s * n` for strings. */
export function repeatString(s, n) {
  return n <= 0 ? '' : s.repeat(n);
}

/** Number of code points in `s` (Python's `len()` for a str). */
export function codePointLength(s) {
  let n = 0;
  for (let i = 0; i < s.length; i += 1) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
      const next = s.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i += 1;
    }
    n += 1;
  }
  return n;
}

/** First `n` code points of `s` (Python's `s[:n]`). */
export function sliceCodePoints(s, n) {
  if (n <= 0) return '';
  let count = 0;
  let i = 0;
  while (i < s.length && count < n) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
      const next = s.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i += 1;
