/**
 * Python's `repr()` for the handful of types this program prints: str, int, dict
 * and list.
 *
 * Value mapping used throughout the port:
 *   JS string  -> Python str
 *   JS BigInt  -> Python int  (Python ints are arbitrary precision)
 *   JS Map     -> Python dict (insertion ordered, as of CPython 3.7)
 *   JS Array   -> Python list
 */

import { isPrintable } from './unicode.mjs';

function hexEscape(cp) {
  if (cp <= 0xff) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp <= 0xffff) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a str, following CPython's `unicode_repr`.
 *
 * The quote character is a single quote unless the string contains one and no
 * double quote, in which case double quotes avoid the need to escape.
 */
export function reprStr(s) {
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) quote = '"';

  let out = quote;
  for (const ch of s) {
    if (ch === quote || ch === '\\') {
      out += `\\${ch}`;
      continue;
    }
    if (ch === '\t') { out += '\\t'; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r') { out += '\\r'; continue; }

    const cp = ch.codePointAt(0);
    if (cp < 0x20 || cp === 0x7f) {
      out += hexEscape(cp);
    } else if (cp < 0x7f) {
      out += ch;
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      out += hexEscape(cp);
    }
  }
  return out + quote;
}

/** `repr()` of an int. */
export function reprInt(value) {
  return value.toString();
}

/** `repr()` of any value this program can print. */
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const parts = [];
    for (const [key, val] of value) parts.push(`${pyRepr(key)}: ${pyRepr(val)}`);
    return `{${parts.join(', ')}}`;
  }
  throw new TypeError(`pyRepr: unsupported value ${typeof value}`);
}

