/**
 * Python's `int(str)` conversion.
 *
 * CPython first runs the text through `_PyUnicode_TransformDecimalAndSpaceToASCII`,
 * which folds every Unicode decimal digit down to its ASCII equivalent and every
 * whitespace code point to a plain space.  The resulting ASCII string is then
 * parsed by the ordinary integer scanner, which allows surrounding spaces, one
 * optional sign, and single underscores strictly between digits.
 */

import { isDecimalDigit, decimalDigitValue, isPySpace } from './unicode.mjs';

function transformDecimalAndSpaceToAscii(s) {
  let out = '';
  for (const ch of s) {
    if (isPySpace(ch)) {
      out += ' ';
    } else if (ch >= '0' && ch <= '9') {
      out += ch;
    } else if (isDecimalDigit(ch)) {
      out += String(decimalDigitValue(ch));
    } else {
      out += ch;
    }
  }
  return out;
}

/**
 * Parse `text` the way `int()` does.
 *
 * @returns {{ok: true, value: bigint} | {ok: false}}
 */
export function pyInt(text) {
  const s = transformDecimalAndSpaceToAscii(text);

  let start = 0;
  let end = s.length;
  while (start < end && s[start] === ' ') start += 1;
  while (end > start && s[end - 1] === ' ') end -= 1;

  let negative = false;
  if (start < end && (s[start] === '+' || s[start] === '-')) {
    negative = s[start] === '-';
    start += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (let i = start; i < end; i += 1) {
    const ch = s[i];
    if (ch === '_') {
      // An underscore is only legal between two digits.
      if (!previousWasDigit) return { ok: false };
      previousWasDigit = false;
      continue;
    }
    if (ch < '0' || ch > '9') return { ok: false };
    digits += ch;
    previousWasDigit = true;
  }
  if (!previousWasDigit) return { ok: false };

  const magnitude = BigInt(digits);
  return { ok: true, value: negative ? -magnitude : magnitude };
}

