 * and the junk-absorbing extensions around a longest match), because different
 * opcode choices would produce a different -- though still valid -- diff text.
 */

/** Longest matching block of `a[alo:ahi]` against `b[blo:bhi]`. */
function findLongestMatch(a, b, b2j, bjunk, alo, ahi, blo, bhi) {
  let besti = alo;
  let bestj = blo;
  let bestsize = 0;

  let j2len = new Map();
  for (let i = alo; i < ahi; i += 1) {
    const newj2len = new Map();
    const indices = b2j.get(a[i]);
    if (indices !== undefined) {
      for (const j of indices) {
        if (j < blo) continue;
        if (j >= bhi) break;
        const k = (j2len.get(j - 1) || 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
    }
    j2len = newj2len;
  }

