  while (besti > alo && bestj > blo && !bjunk.has(b[bestj - 1]) && a[besti - 1] === b[bestj - 1]) {
    besti -= 1;
    bestj -= 1;
    bestsize += 1;
  }
  while (
    besti + bestsize < ahi && bestj + bestsize < bhi &&
    !bjunk.has(b[bestj + bestsize]) && a[besti + bestsize] === b[bestj + bestsize]
  ) {
    bestsize += 1;
  }
  // ... then absorb any adjacent junk that also happens to match.
  while (besti > alo && bestj > blo && bjunk.has(b[bestj - 1]) && a[besti - 1] === b[bestj - 1]) {
    besti -= 1;
    bestj -= 1;
    bestsize += 1;
