/**
 * Access to the process arguments as Python sees them.
 *
 * CPython decodes `argv` with the filesystem encoding and the `surrogateescape`
 * error handler, so a byte that is not valid UTF-8 survives as a lone surrogate in
 * the range U+DC80..U+DCFF rather than being replaced.  Node decodes `process.argv`
 * with U+FFFD replacement instead, which would lose information, so the raw bytes
 * are recovered from `/proc/self/cmdline` where that is available.
 */

import { readFileSync } from 'node:fs';

/** Decode UTF-8 bytes, mapping undecodable bytes to lone surrogates. */
export function decodeSurrogateEscape(buf) {
  let out = '';
  let i = 0;
  while (i < buf.length) {
    const b0 = buf[i];
    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
      continue;
    }

    let need = 0;
    let value = 0;
    let minimum = 0;
    if (b0 >= 0xc2 && b0 <= 0xdf) { need = 1; value = b0 & 0x1f; minimum = 0x80; }
    else if (b0 >= 0xe0 && b0 <= 0xef) { need = 2; value = b0 & 0x0f; minimum = 0x800; }
    else if (b0 >= 0xf0 && b0 <= 0xf4) { need = 3; value = b0 & 0x07; minimum = 0x10000; }
    else { out += String.fromCharCode(0xdc00 + b0); i += 1; continue; }

    let valid = true;
    for (let k = 1; k <= need; k += 1) {
      const bk = buf[i + k];
      if (bk === undefined || (bk & 0xc0) !== 0x80) { valid = false; break; }
      value = (value << 6) | (bk & 0x3f);
    }
    if (valid && (value < minimum || value > 0x10ffff || (value >= 0xd800 && value <= 0xdfff))) {
      valid = false;
    }
    if (!valid) {
      // Only the leading byte is consumed; the rest are re-examined so that each
      // undecodable byte produces its own escape, matching CPython.
      out += String.fromCharCode(0xdc00 + b0);
      i += 1;
      continue;
    }
    out += String.fromCodePoint(value);
    i += need + 1;
  }
  return out;
}

/** Encode a string back to bytes, turning lone U+DC80..U+DCFF back into raw bytes. */
export function encodeSurrogateEscape(s) {
  const chunks = [];
  let plain = '';
  for (let i = 0; i < s.length; i += 1) {
    const code = s.charCodeAt(i);
    if (code >= 0xdc80 && code <= 0xdcff) {
      if (plain) { chunks.push(Buffer.from(plain, 'utf8')); plain = ''; }
      chunks.push(Buffer.from([code - 0xdc00]));
    } else {
      plain += s[i];
    }
  }
  if (plain) chunks.push(Buffer.from(plain, 'utf8'));
  return Buffer.concat(chunks);
}

/**
 * The script's own arguments (everything after the script path), decoded the way
 * Python would decode them.
 */
export function getScriptArgs() {
  const fallback = process.argv.slice(2);
  try {
    const raw = readFileSync('/proc/self/cmdline');
    const parts = [];
    let start = 0;
    for (let i = 0; i < raw.length; i += 1) {
      if (raw[i] === 0) {
        parts.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) parts.push(raw.subarray(start));
    // The script's arguments are always the trailing entries, regardless of any
    // interpreter options that appear earlier on the real command line.
    if (parts.length < fallback.length) return fallback;
    const tail = parts.slice(parts.length - fallback.length);
    return tail.map(decodeSurrogateEscape);
  } catch {
    return fallback;
  }
}

/** Basename of the script path, which is what argparse uses for `prog`. */
export function getProgName() {
  const path = process.argv[1] || '';
  const idx = path.lastIndexOf('/');
  return idx === -1 ? path : path.slice(idx + 1);
}

