    const removedValues = new Map();
    const valuesChanged = new Map();
    const changedValues = new Map();
    const typeChanges = new Map();

    for (const key of t2.keys()) {
      if (!t1.has(key)) {
        added.push(pathFor(key));
        addedValues.set(pathFor(key), t2.get(key));
      }
    }
    for (const key of t1.keys()) {
      if (!t2.has(key)) {
        removed.push(pathFor(key));
        removedValues.set(pathFor(key), t1.get(key));
      }
    }
    for (const key of t1.keys()) {
      if (!t2.has(key)) continue;
      const oldValue = t1.get(key);
      const newValue = t2.get(key);
      const path = pathFor(key);

      if (typeName(oldValue) !== typeName(newValue)) {
        typeChanges.set(path, new Map([
          ['old_type', typeName(oldValue)],
          ['new_type', typeName(newValue)],
          ['old_value', oldValue],
          ['new_value', newValue],
        ]));
        continue;
      }
      if (pyEqual(oldValue, newValue)) continue;

      const entry = new Map([['new_value', newValue], ['old_value', oldValue]]);
      if (typeof oldValue === 'string' && typeof newValue === 'string') {
        const diff = stringDiff(oldValue, newValue);
        if (diff !== null) entry.set('diff', diff);
      }
      valuesChanged.set(path, entry);
      changedValues.set(path, newValue);
    }

    this.categories = {
      type_changes: typeChanges,
      dictionary_item_added: added,
      dictionary_item_removed: removed,
      values_changed: valuesChanged,
    };
    this.addedValues = addedValues;
    this.removedValues = removedValues;
    this.changedValues = changedValues;

    const text = new Map();
    for (const category of CATEGORY_ORDER) {
      const value = this.categories[category];
      const empty = Array.isArray(value) ? value.length === 0 : value.size === 0;
      if (!empty) text.set(category, value);
    }
    this.text = text;
  }

  /**
   * The mapping a Delta is built from: directed (no `old_value`), and with the
   * added-item paths resolved to the values they refer to.
   */
  toDeltaDict() {
    const out = new Map();
    for (const category of CATEGORY_ORDER) {
      const value = this.categories[category];
      if (category === 'dictionary_item_added' || category === 'dictionary_item_removed') {
        if (!value.length) continue;
        const source = category === 'dictionary_item_added' ? this.addedValues : this.removedValues;
        const mapping = new Map();
        for (const path of value) mapping.set(path, source.get(path));
        out.set(category, mapping);
        continue;
      }
      if (!value.size) continue;
      if (category === 'values_changed') {
        const mapping = new Map();
        for (const [path, entry] of value) {
          mapping.set(path, new Map([['new_value', entry.get('new_value')]]));
        }
        out.set(category, mapping);
        continue;
      }
      out.set(category, value);
    }
    return out;
  }
}

