/**
 * Port of dataset/test15.py: compare a handful of small dictionaries built from
 * three command-line arguments, printing each DeepDiff and Delta.
 *
 * Run as: node test15.mjs --a <str> --b <int> --c <int>
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { getScriptArgs, getProgName } from './lib/py_argv.mjs';
import { pyInt } from './lib/py_int.mjs';
import { pyRepr } from './lib/py_repr.mjs';
import { repeatString } from './lib/py_string.mjs';
import { DeepDiff } from './lib/deepdiff.mjs';
import { Delta } from './lib/delta.mjs';
import { print, flush } from './lib/py_stdio.mjs';

/** `type=str`: accepts anything. */
const strType = (value) => ({ ok: true, value });
strType.typeName = 'str';

/** `type=int`: Python's int() conversion. */
const intType = (value) => pyInt(value);
intType.typeName = 'int';

const parser = new ArgumentParser(getProgName());
parser.addArgument('--a', { type: strType, required: true });
parser.addArgument('--b', { type: intType, required: true });
parser.addArgument('--c', { type: intType, required: true });
const args = parser.parseArgs(getScriptArgs());

const a = args.get('a');
const b = args.get('b');
const c = args.get('c');

const obj1 = new Map([['x', a], ['y', b]]);
const obj2 = new Map([['x', a], ['y', c]]);
const obj3 = new Map([['x', repeatString(a, 2)], ['y', b]]);
const obj4 = new Map([['x', a], ['y', b], ['z', c]]);

const diff1 = new DeepDiff(obj1, obj2); // compare obj1 and obj2
print(pyRepr(diff1.text));
const delta1 = new Delta(diff1); // build a delta
print(delta1.toString());
const result1 = new Map(obj1); // update obj1 with obj2
for (const [key, value] of obj2) result1.set(key, value);
print(pyRepr(result1));
const diff2 = new DeepDiff(obj1, obj3); // compare obj1 and obj3
print(pyRepr(diff2.text));
const delta2 = new Delta(diff2); // build the second delta
print(delta2.toString());
const diff3 = new DeepDiff(obj1, obj4); // compare obj1 and obj4
print(pyRepr(diff3.text));
const delta3 = new Delta(diff3); // build the third delta
print(delta3.toString());
const result2 = new Map([['x', repeatString(a, 2)], ['y', c]]); // build a new object
print(pyRepr(result2));
const diff4 = new DeepDiff(result2, obj4); // compare the result with obj4
print(pyRepr(diff4.text));
const diff5 = new DeepDiff(obj2, obj3); // compare obj2 and obj3
print(pyRepr(diff5.text));
const diff6 = new DeepDiff(obj3, obj4); // compare obj3 and obj4
print(pyRepr(diff6.text));
const diff7 = new DeepDiff(obj2, obj4); // compare obj2 and obj4
print(pyRepr(diff7.text));

flush();

