/**
 * A focused reimplementation of the `argparse` behaviour this program depends on:
 * three required long options with `type=str`/`type=int`, the automatic `-h`, and
 * the exact usage/help/error text CPython's argparse emits.
 */

import { reprStr } from './py_repr.mjs';
import { print, printErr, exit } from './py_stdio.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Thrown for the conditions argparse reports through `parser.error()`. */
class ParserError extends Error {}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    /** Actions in definition order; `-h` is registered first, as argparse does. */
    this.actions = [
      { optionStrings: ['-h', '--help'], dest: 'help', nargs: 0, metavar: null, help: 'show this help message and exit' },
    ];
    this.optionStringActions = new Map();
    for (const opt of this.actions[0].optionStrings) this.optionStringActions.set(opt, this.actions[0]);
  }

  addArgument(optionString, { type, required }) {
    const dest = optionString.replace(/^-+/, '');
    const action = {
      optionStrings: [optionString],
      dest,
      nargs: 1,
      metavar: dest.toUpperCase(),
      type,
      required,
      help: null,
    };
    this.actions.push(action);
    this.optionStringActions.set(optionString, action);
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const opt = action.optionStrings[0];
      if (action.nargs === 0) return `[${opt}]`;
      return `${opt} ${action.metavar}`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => (
      action.nargs === 0
        ? action.optionStrings.join(', ')
        : `${action.optionStrings[0]} ${action.metavar}`
    ));
    // argparse indents actions by two columns and places help text at
    // min(max_action_length + 2, max_help_position) where max_help_position is 24.
    const actionMaxLength = Math.max(...invocations.map((s) => s.length + 2));
    const helpPosition = Math.min(actionMaxLength + 2, 24);

    let out = this.formatUsage();
    out += '\noptions:\n';
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        out += `  ${invocation}\n`;
        return;
      }
      const padded = `  ${invocation}`.padEnd(helpPosition, ' ');
      out += `${padded}${action.help}\n`;
    });
    return out;
  }

  error(message) {
    printErr(this.formatUsage());
    printErr(`${this.prog}: error: ${message}\n`);
    exit(2);
  }

  /**
   * argparse's `_parse_optional`: decide whether `argString` names an option, and
   * if so which one and whether a value was attached with `=`.
   *
   * Returns `null` when the token should be treated as a positional.
   */
  #parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;
    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    if (argString.includes('=')) {
      const eq = argString.indexOf('=');
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this.optionStringActions.has(optionString)) {
        return { action: this.optionStringActions.get(optionString), optionString, explicitArg };
      }
    }

    const candidates = this.#getOptionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((c) => c.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (candidates.length === 1) return candidates[0];

    // A bare negative number is a positional as long as no option looks numeric.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse's `_get_option_tuples`: abbreviation matching. */
  #getOptionTuples(argString) {
    const result = [];
    if (argString[0] === '-' && argString[1] === '-') {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const eq = argString.indexOf('=');
        optionPrefix = argString.slice(0, eq);
        explicitArg = argString.slice(eq + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push({ action, optionString, explicitArg });
      }
    } else if (argString[0] === '-' && argString[1] !== '-') {
      const optionPrefix = argString;
      const explicitArg = argString.slice(1);
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
    }
    return result;
  }

  #convert(action, optionString, value) {
    if (!action.type) return value;
    const parsed = action.type(value);
    if (!parsed.ok) {
      throw new ParserError(`argument ${optionString}: invalid ${action.type.typeName} value: ${reprStr(value)}`);
    }
    return parsed.value;
  }

  parseArgs(argStrings) {
    // Classify every token up front, exactly as argparse builds its pattern string.
    const optionTuples = new Array(argStrings.length).fill(null);
    const pattern = [];
    let sawDoubleDash = false;
    for (let i = 0; i < argStrings.length; i += 1) {
      if (!sawDoubleDash && argStrings[i] === '--') {
        sawDoubleDash = true;
        pattern.push('-');
        continue;
      }
      if (sawDoubleDash) {
        pattern.push('A');
        continue;
      }
      const tuple = this.#parseOptional(argStrings[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples[i] = tuple;
        pattern.push('O');
      }
    }

    const namespace = new Map();
    const seen = new Set();
    const extras = [];

    let i = 0;
    try {
      while (i < argStrings.length) {
        if (pattern[i] !== 'O') {
          // No positional actions are defined, so anything else is left over.
          if (pattern[i] !== '-') extras.push(argStrings[i]);
          i += 1;
          continue;
        }

        const { action, optionString, explicitArg } = optionTuples[i];
        if (action === null) {
          extras.push(argStrings[i]);
          i += 1;
          continue;
        }

        seen.add(action);
        if (action.nargs === 0) {
          if (explicitArg !== null) {
            throw new ParserError(`argument ${optionString}: ignored explicit argument ${reprStr(explicitArg)}`);
          }
          if (action.dest === 'help') {
            print(this.formatHelp().replace(/\n$/, ''));
            exit(0);
          }
          i += 1;
          continue;
        }

        if (explicitArg !== null) {
          namespace.set(action.dest, this.#convert(action, optionString, explicitArg));
          i += 1;
          continue;
        }
        if (i + 1 < argStrings.length && pattern[i + 1] === 'A') {
          namespace.set(action.dest, this.#convert(action, optionString, argStrings[i + 1]));
          i += 2;
          continue;
        }
        throw new ParserError(`argument ${optionString}: expected one argument`);
      }

      const missing = this.actions
        .filter((action) => action.required && !seen.has(action))
        .map((action) => action.optionStrings[0]);
      if (missing.length) {
        throw new ParserError(`the following arguments are required: ${missing.join(', ')}`);
      }
    } catch (err) {
      if (err instanceof ParserError) this.error(err.message);
      throw err;
    }

    if (extras.length) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }
}

