/**
 * The size-bounded JSON rendering used when a Delta is displayed.
 *
 * A Delta prints as `<Delta: JSON>` where the JSON is passed through a summarizer
 * that keeps the representation small.  Three behaviours were established by
 * measuring the reference implementation across its boundaries:
 *
 *   1. The structure is rendered in full when its *content* size -- the sum of
 *      every key's length plus every scalar's textual length, ignoring JSON
 *      punctuation and quoting -- is at most 100.
 *   2. Otherwise each scalar is clipped to a budget derived by walking down from
 *      the root: a mapping hands each child roughly half of what remains after
 *      accounting for the key, and a budget that has become very small collapses
 *      the scalar to a single character.
 *   3. A clipped number is reinterpreted as a number, so it stays unquoted; when
 *      the clipped text is no longer a valid integer (a lone minus sign, say) it
 *      degrades to a JSON string.
 *
 * Boundary evidence (max content size 100, inclusive):
 *   {"values_changed": {"root['y']": {"new_value": N}}}   keys 14+9+9=32
 *       -> full while len(str(N)) <= 68, else clipped to 1 character
 *   {"dictionary_item_added": {"root['z']": N}}           keys 21+9=30
 *       -> full while len(str(N)) <= 70, else clipped to 14 characters
 */

import { jsonDumps } from './py_json.mjs';
import { pyInt } from './py_int.mjs';
import { codePointLength, sliceCodePoints } from './py_string.mjs';

export const DEFAULT_MAX_LENGTH = 100;

function scalarText(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'bigint') return value.toString();
  throw new TypeError(`summarize: unsupported scalar ${typeof value}`);
}

/** Sum of all key lengths and scalar text lengths in `value`. */
export function contentSize(value) {
  if (value instanceof Map) {
    let total = 0;
    for (const [key, child] of value) total += codePointLength(key) + contentSize(child);
    return total;
  }
  if (Array.isArray(value)) {
    let total = 0;
    for (const child of value) total += contentSize(child);
    return total;
  }
  return codePointLength(scalarText(value));
}

function clip(text, budget) {
  // Once the budget has shrunk to almost nothing, only a single character is kept.
  if (budget <= 5) return sliceCodePoints(text, 1);
  return sliceCodePoints(text, budget);
}

function shrink(value, budget) {
  if (value instanceof Map) {
    const out = new Map();
    for (const [key, child] of value) {
      out.set(key, shrink(child, Math.floor((budget - codePointLength(key) - 1) / 2)));
    }
    return out;
  }
  if (Array.isArray(value)) return value.map((child) => shrink(child, budget));
  if (typeof value === 'string') return clip(value, budget);

  const clipped = clip(scalarText(value), budget);
  const reparsed = pyInt(clipped);
  return reparsed.ok ? reparsed.value : clipped;
}

/** Render `value` as JSON, clipping scalars when it would otherwise be too large. */
export function summarize(value, maxLength = DEFAULT_MAX_LENGTH) {
  if (contentSize(value) <= maxLength) return jsonDumps(value);
  return jsonDumps(shrink(value, maxLength));
}

