/**
 * `json.dumps` compatible serialization.
 *
 * Matches CPython's defaults: `ensure_ascii=True` and the `', '` / `': '`
 * separators.  Non-ASCII code points become `\uXXXX`, with astral characters
 * emitted as UTF-16 surrogate pairs exactly as the C encoder does.
 */

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['"', '\\"'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/** `json.encoder.py_encode_basestring_ascii` for a single string. */
export function encodeStringAscii(s) {
  let out = '"';
  // Iterate UTF-16 units so that astral characters naturally yield the surrogate
  // pair escapes that ensure_ascii produces.
  for (let i = 0; i < s.length; i += 1) {
    const ch = s[i];
    const short = SHORT_ESCAPES.get(ch);
    if (short !== undefined) {
      out += short;
      continue;
    }
    const code = s.charCodeAt(i);
    if (code >= 0x20 && code <= 0x7e) {
      out += ch;
    } else {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
    }
  }
  return out + '"';
}

/**
 * `json.dumps(value)` for the value shapes this program serializes.
 *
 * A value exposing `toJsonText()` is spliced in verbatim, which lets the summarizer
 * emit a clipped number without it being re-quoted as a string.
 */
export function jsonDumps(value) {
  if (typeof value === 'string') return encodeStringAscii(value);
  if (typeof value === 'bigint') return value.toString();
  if (value !== null && typeof value === 'object' && typeof value.toJsonText === 'function') {
    return value.toJsonText();
  }
  if (Array.isArray(value)) return `[${value.map(jsonDumps).join(', ')}]`;
  if (value instanceof Map) {
    const parts = [];
    for (const [key, val] of value) parts.push(`${encodeStringAscii(key)}: ${jsonDumps(val)}`);
    return `{${parts.join(', ')}}`;
  }
  throw new TypeError(`jsonDumps: unsupported value ${typeof value}`);
}

