// Generate a large randomized case set for the differential harness.
const NUL = String.fromCharCode(0);

// Deterministic PRNG so a failing run can be reproduced.
let seed = 0x2f6e2b1;
function rnd() {
  seed ^= seed << 13; seed >>>= 0;
  seed ^= seed >>> 17;
  seed ^= seed << 5; seed >>>= 0;
  return seed / 0x100000000;
}
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

const ALPHABETS = [
  'ab',
  'abcdefghij',
  '0123456789',
  "'\"\\",
  '\n',
  '\r\n',
  '\t ',
  'üßé中文',
  '\u{1F600}\u{1F601}',
  ' ​  ́',
  '�',
  ' ',
  'a\nb',
];

function randomString() {
  const mode = int(0, 9);
  if (mode === 0) return '';
  if (mode === 1) {
    // Line-structured input, which exercises the unified-diff attachment.
    const lines = int(1, 40);
    const out = [];
    for (let i = 0; i < lines; i += 1) out.push(pick(['x', 'y', 'zz', `L${i}`, '', 'same', 'aaa']));
    return out.join(pick(['\n', '\r\n', '\r', ' ', '']));
  }
  if (mode === 2) {
    // Lengths right around the summarizer's gate for the doubled string.
    const n = int(28, 40);
    return pick(['a', 'ü', '\u{1F600}', '"', '\t', ' ']).repeat(n);
  }
  const alphabet = pick(ALPHABETS);
  const chars = [...alphabet];
  const n = int(1, 60);
  let s = '';
  for (let i = 0; i < n; i += 1) s += pick(chars);
  return s;
}

function randomInt() {
  const mode = int(0, 8);
  if (mode === 0) return String(int(-9, 9));
  if (mode === 1) return String(int(-100000, 100000));
  if (mode === 2) {
    const digits = int(60, 80);
    let s = '';
    for (let i = 0; i < digits; i += 1) s += String(int(i === 0 ? 1 : 0, 9));
    return (rnd() < 0.4 ? '-' : '') + s;
  }
  if (mode === 3) {
    const digits = int(1, 400);
    let s = '';
    for (let i = 0; i < digits; i += 1) s += String(int(i === 0 ? 1 : 0, 9));
    return (rnd() < 0.3 ? '-' : '') + s;
  }
  if (mode === 4) return pick([' 5 ', '+5', '007', '1_000', '1_0_0_0', '\t9\n', ' 5']);
  if (mode === 5) return pick(['٥', '९', '５', '٥٩', '\u{1D7D8}\u{1D7D9}']);
  if (mode === 6) return pick(['', ' ', '-', '+', '5.0', '0x1', 'abc', '1_', '_1', '1__0', 'None', '²', '−5', '1 2']);
  if (mode === 7) return String(int(0, 1)) + (rnd() < 0.5 ? '' : '0'.repeat(int(1, 5)));
  return pick(['0', '-0', '+0', '00', '-00']);
}

const cases = [];
for (let i = 0; i < 900; i += 1) {
  const roll = rnd();
  if (roll < 0.06) {
    // Occasionally exercise the CLI surface itself.
    const tokens = [];
    const n = int(0, 6);
    for (let k = 0; k < n; k += 1) {
      tokens.push(pick(['--a', '--b', '--c', '-h', '--help', '--h', '--', '-', '-x', '--d',
        'x', '1', '-5', '--a=1', '--b=2', '--c=3', '=', '--a=']));
    }
    cases.push(tokens);
    continue;
  }
  const b = randomInt();
  const c = rnd() < 0.25 ? b : randomInt();
  cases.push(['--a', randomString(), '--b', b, '--c', c]);
}

const lines = cases.map((a) => Buffer.from(a.length ? a.join(NUL) + NUL : '', 'utf8').toString('base64'));
process.stdout.write(`${lines.join('\n')}\n`);

